            var failure = org.assertj.core.api.Assertions.catchThrowable(() -> {
                try (var update = connection.prepareStatement("UPDATE claims SET member_id='member-2', policy_limit=1, currency='CAD' WHERE id=?")) {
                    update.setObject(1, id); update.executeUpdate();
                }
            });
            assertThat(failure).isNotNull();
        }
    }
}
